create extension if not exists pgcrypto;
create table if not exists seasons(id uuid primary key default gen_random_uuid(), name text not null, status text not null default 'active', created_at timestamptz default now(), finished_at timestamptz, champion_club_id uuid);
create table if not exists users(id uuid primary key default gen_random_uuid(), telegram_id bigint unique not null, username text, first_name text, last_name text, created_at timestamptz default now());
create table if not exists clubs(id text primary key, name text unique not null, logo_url text);
create table if not exists registrations(id uuid primary key default gen_random_uuid(), season_id uuid not null references seasons(id) on delete cascade, user_id uuid not null references users(id) on delete cascade, telegram_id bigint not null, club_id text not null references clubs(id), club_name text not null, created_at timestamptz default now(), unique(season_id,user_id), unique(season_id,club_id));
create table if not exists rounds(id uuid primary key default gen_random_uuid(), season_id uuid not null references seasons(id) on delete cascade, round_no int not null, status text not null default 'locked', opened_at timestamptz, deadline_at timestamptz, warning_sent boolean default false, unique(season_id,round_no));
create table if not exists matches(id uuid primary key default gen_random_uuid(), season_id uuid not null references seasons(id) on delete cascade, round_no int not null, home_club_id text not null references clubs(id), away_club_id text not null references clubs(id), home_user_id uuid references users(id), away_user_id uuid references users(id), status text not null default 'scheduled', home_goals int default 0, away_goals int default 0, submitted_by uuid references users(id), submitted_at timestamptz, confirmed_by uuid references users(id), confirmed_at timestamptz, rejected_by uuid references users(id), auto_result boolean default false, deadline_at timestamptz, created_at timestamptz default now());
create table if not exists sessions(user_id uuid primary key references users(id) on delete cascade, type text, match_id uuid references matches(id) on delete set null, updated_at timestamptz default now());
